import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs['views'].get('camera')
    offset=0.0
    if cam:
        th=math.radians(obs['rig']['trailer_heading_deg'])
        sides=[[],[]]
        for b,d in cam.get('walls',[]):
            a=math.radians(b)
            dx=d*math.cos(a); dy=d*math.sin(a)
            s=-dx*math.cos(th)-dy*math.sin(th)
            y=-dx*math.sin(th)+dy*math.cos(th)
            if s>0.4 and abs(y)>0.35:
                sides[0 if y>0 else 1].append((s,y))
        for side in sides: side.sort()
        def interp(points,s):
            if not points: return None
            for i in range(len(points)-1):
                a,b=points[i],points[i+1]
                if a[0]<=s<=b[0] and b[0]>a[0]:
                    return a[1]+(b[1]-a[1])*(s-a[0])/(b[0]-a[0])
            p=min(points,key=lambda p:abs(p[0]-s))
            return p[1] if abs(p[0]-s)<0.8 else None
        vals=[]
        for s in (2.0,2.5,3.0):
            a=interp(sides[0],s); b=interp(sides[1],s)
            if a is not None and b is not None: vals.append((a+b)/2)
        if vals: offset=sum(vals)/len(vals)
    desired=max(-32,min(32,17*offset))
    steer=max(-34,min(34,1.8*h-2.0*desired))
    return steer,-0.7,-23

