 x+=v*math.cos(a+da/2)*dt; y+=v*math.sin(a+da/2)*dt; a+=da
 t=o['t']
 for name,view in o['views'].items():
  if name=='periphery' or not view: continue
  ox,oy=view['origin']
  for b,d in view.get('walls',[]):
   if d>18: continue
   b=math.radians(b); px=ox+d*math.cos(b); py=oy+d*math.sin(b)
   pts.append((x+px*math.cos(a)-py*math.sin(a),y+px*math.sin(a)+py*math.cos(a),t))
 pts=[p for p in pts if t-p[2]<22][-2200:]
 h=o['hitch_deg']; th=a-math.radians(h); rx,ry=o['rig']['trailer_rear']; wx=x+rx*math.cos(a)-ry*math.sin(a); wy=y+rx*math.sin(a)+ry*math.cos(a)
 local=[]
 for px,py,tt in pts:
  dx=px-wx; dy=py-wy; s=-dx*math.cos(th)-dy*math.sin(th); z=-dx*math.sin(th)+dy*math.cos(th)
  if -2<s<8 and 1.3<abs(z)<8: local.append((s,z))
 goals=[]
 for ss in (2,3.5,5):
  sides=[]
  for sign in (-1,1):
   arr=sorted((abs(s-ss),z) for s,z in local if z*sign>0 and abs(s-ss)<1)[:12]
   if arr:
    zs=sorted(z for _,z in arr); sides.append(zs[len(zs)//2]-sign*2.65)
  if sides: goals.append((ss,sum(sides)/len(sides)))
 if goals:
  ss,z=goals[-1]; target=math.degrees(math.atan(7.2*z/(ss*ss+z*z)))
  target=max(-25,min(25,target)); filt+=min(1,dt/1.2)*(target-filt)
 steer=max(-42,min(42,0.51*h+1.8*(h-filt)))
 if abs(h)>38:
  wake('Hitch needs review'); return steer,0,-165
 if int(t*10)%30==0: print('path',goals,'h',round(h,1),'desired',round(filt,1))
 return steer,-0.5,-165

